#include <cstddef>
#include <iostream>
#include <limits>

int main() {
    const unsigned int biggest = std::numeric_limits<unsigned int>::max();
    unsigned int counter = 0u;

    counter -= 1u; // wraps around to the largest value
    std::cout << counter << ' ' << biggest << '\n';
    counter += 1u; // wraps back to 0
    std::cout << counter << '\n';

    std::cout << sizeof(std::size_t) << '\n';
    return 0;
}

