#include <iostream>
#include <limits>

int main() {
    unsigned int u = std::numeric_limits<unsigned int>::max();
    u += 2u;
    std::cout << u << '\n';

    unsigned int low = 5u;
    low -= 10u;
    std::cout << low << '\n';
    return 0;
}
